import json

with open('/tmp/axp_data.json') as f:
    data = json.load(f)

monthly = data['monthly']
yearly = data['yearly']
vol_yearly = data['vol_yearly']
div_events = data['div_events']
decade_data = data['decade_data']

# Build JS data strings
monthly_labels = json.dumps([d['ym'] for d in monthly])
monthly_closes = json.dumps([d['close'] for d in monthly])

yearly_labels = json.dumps([d['year'] for d in yearly])
yearly_closes = json.dumps([d['close'] for d in yearly])
yearly_rets = json.dumps([d['ret'] for d in yearly])

vol_labels = json.dumps([d['year'] for d in vol_yearly])
vol_avg = json.dumps([d['avg'] for d in vol_yearly])

div_dates = json.dumps([d['date'] for d in div_events])
div_amts = json.dumps([d['amt'] for d in div_events])
div_closes = json.dumps([d['close'] for d in div_events])

decade_labels = json.dumps([d['d'] for d in decade_data])
decade_ret = json.dumps([d['ret'] for d in decade_data])
decade_cagr = json.dumps([d['cagr'] for d in decade_data])
decade_vol = json.dumps([d['vol'] for d in decade_data])
